echo "update 'slang'..."
rm -rf "build"
rm -rf "../../../../../AE-Bin/external/linux-x64/slang"
rm -rf "temp"
mkdir "build"
git clone --recurse-submodules --branch "v2025.17" "../../../../../3party/slang" "temp"
cp "temp/CMakeLists.txt" "temp/origin_CMakeLists.txt"
cp "slang_CMakeLists.txt" "temp/CMakeLists.txt"
cmake -S temp -B build -G "Unix Makefiles" -DAE_ENABLE_COMPILER_WARNINGS=OFF -DCMAKE_BUILD_TYPE=Debug -DAE_SIMD_SSE=20 -DAE_SIMD_AES=0 -DCMAKE_INSTALL_PREFIX="../../../../../AE-Bin/external/linux-x64/slang" 
cmake --build build --config Debug --target "slang" -j 8
cmake -S temp -B build -G "Unix Makefiles" -DAE_ENABLE_COMPILER_WARNINGS=OFF -DCMAKE_BUILD_TYPE=Release -DAE_SIMD_SSE=20 -DAE_SIMD_AES=0 -DCMAKE_INSTALL_PREFIX="../../../../../AE-Bin/external/linux-x64/slang" 
cmake --build build --config Release --target "slang" -j 8
mkdir "../../../../../AE-Bin/external/linux-x64/slang"
mkdir "../../../../../AE-Bin/external/linux-x64/slang/include"
mkdir "../../../../../AE-Bin/external/linux-x64/slang/lib"
cp "temp/LICENSE" "../../../../../AE-Bin/external/linux-x64/slang/slang-LICENSE.txt"
cp "temp/include/slang.h" "../../../../../AE-Bin/external/linux-x64/slang/include/slang.h"
cp "temp/include/slang-deprecated.h" "../../../../../AE-Bin/external/linux-x64/slang/include/slang-deprecated.h"
cp "temp/include/slang-image-format-defs.h" "../../../../../AE-Bin/external/linux-x64/slang/include/slang-image-format-defs.h"
cp "build/Debug/lib/libslangd.so" "../../../../../AE-Bin/external/linux-x64/slang/lib/libslangd.so"
cp "build/Release/lib/libslang.so" "../../../../../AE-Bin/external/linux-x64/slang/lib/libslang.so"
rm -rf "temp"
rm -rf "build"
read -p "press any key..."
